        public static int LineCap8d(int[] caps, int max)
        {
            if (caps == null) return max;
            if (OnePitState.Chapter >= 2) return max;
            int ix = Mathf.Clamp(Mathf.Min(ChapterLine.LevelIx, HallUpgrades.DeskLevel), 0, caps.Length - 1);
            return Mathf.Min(max, caps[ix]);
        }''','''        /// Потолок строки. Решение Максима 02.11 (ГС 19:44, п. 1): рабочего стола и потолка прокачек нет — вся лестница открыта сразу,
        /// единственный ограничитель — цена (таблицы caps модели остались только для `Econ8dCaps`: тесты, сравнение).
        public static int LineCap8d(int[] caps, int max) => max;''')
s=s.replace('''        /// Сколько уровней прокачек откроет следующий слой стола при текущей линии.
        public static int DeskGain8d()
        {
            if (OnePitState.Chapter >= 2) return 0;
            int d = HallUpgrades.DeskLevel, lv = ChapterLine.LevelIx, n = 0;
            for (int i = 0; i < HallUpgrades.Count; i++)
            {
                var c = UpgCaps8d(i);
                if (c == null) continue;
                int a = c[Mathf.Clamp(Mathf.Min(lv, d), 0, c.Length - 1)], b = c[Mathf.Clamp(Mathf.Min(lv, d + 1), 0, c.Length - 1)];
                n += Mathf.Max(0, b - a);
            }
            return n;
        }''','''        /// Стола нет (02.11, решение Максима): слой ничего не открывает.
        public static int DeskGain8d() => 0;''')
