using TMPro;
using UnityEngine;
using Pitt.UI;

namespace Pitt.OnePit
{
    /// Активный бафф «×2 к Яме» (решения Максима 02.11, п. 99 + развилка 10а): пока он идёт, оффер-кнопка исчезает, а на её месте
    /// (над кнопками справа) висит компактная зелёная кнопка «×2 · 3:12» — без значка ▶ и пульса, ≥ 17 пт (таймер, п. 106). Не прячется
    /// при посылке: с кнопкой посылки они стоят друг над другом. Тап — короткая подсказка «Яма ×2: утки считаются дважды». Живёт в слое Action.
    public sealed class BoostChip
    {
        public const float W = 300f, H = 92f;
        /// Позиции (якорь (1,0) слоя Action): над слотом оффера/посылки (RvButton.Pos) или на его месте, если слот пуст.
        public static readonly Vector2 PosFree = RvButton.Pos, PosStacked = RvButton.Pos + new Vector2(0f, RvButton.Size.y * 0.5f + H * 0.5f + 14f);
        public static readonly Color Green = Palette.Hex("#2E9E5B");

        public readonly RectTransform Root;
        readonly Chunky _c;
        readonly TextMeshProUGUI _t;
        readonly CanvasGroup _g;
        readonly Juicy _j;
        readonly UnityEngine.UI.Image _bar;
        float _a, _clock;
        bool _first = true;
        int _sec = -1;

        public bool Shown => Root.gameObject.activeInHierarchy && _a > 0.5f;
        public string Text => _t.text;

        public BoostChip(Transform parent)
        {
            Root = UiKit.Box("BoostChip", parent, new Vector2(W, H), RvButton.Anchor, PosFree);
            _g = U.Group(Root.gameObject);
            _g.alpha = 0f;
            _g.blocksRaycasts = false;
            var body = UiKit.Fill("Body", Root);
            _j = new Juicy(body) { Hz = 4.5f, Zeta = 0.3f };
            _c = Chunky.Make("Btn", body, new Vector2(W, H), Green, 34, 8f, 5f);
            _t = U.Txt(_c.Content, "", UiKit.PriceFont, new Vector2(0f, 6f), UiFont.Title, Color.white, 0.24f, TextAlignmentOptions.Center, W - 28f);
            _t.enableAutoSizing = true; _t.fontSizeMin = UiKit.PriceFont; _t.fontSizeMax = UiKit.PriceFont;
            _t.textWrappingMode = TextWrappingModes.NoWrap;
            _t.raycastTarget = false;
            // полоска остатка: тонкая, светлая, под текстом
            _bar = U.Img(_c.Content, UiKit.RoundedSprite(3), Color.white.A(0.7f), new Vector2(W - 70f, 6f), new Vector2(0f, -H * 0.5f + 17f), "Left");
            _bar.raycastTarget = false;
            _c.Tappable(Tap);
            Root.gameObject.SetActive(false);
        }

        void Tap()
        {
            _c.PressAnim();
            _j.Kick(0.16f);
            U.Sfx(SfxId.Click);
            GoalPlate.Hint("boost", "Яма ×2: утки в Яме считаются дважды. Осталось " + GoalTop.Clock(Mathf.CeilToInt(PitGoal.BoostLeft)), 4f, true);
        }

        /// text — «×2 · 3:12»; frac — доля остатка 0..1; stacked — над слотом посылки.
        public void Tick(float dt, bool visible, string text, float frac, bool stacked)
        {
            if (visible && !Root.gameObject.activeSelf) { Root.gameObject.SetActive(true); _j.Kick(_first ? 0.5f : 0.3f); _first = false; }
            _a = Mathf.MoveTowards(_a, visible ? 1f : 0f, dt / 0.15f);
            _g.alpha = _a;
            _g.blocksRaycasts = visible;
            if (!visible && _a <= 0f) { if (Root.gameObject.activeSelf) Root.gameObject.SetActive(false); return; }
            if (_t.text != text) _t.text = text;
            _bar.rectTransform.sizeDelta = new Vector2((W - 70f) * Mathf.Clamp01(frac), 6f);
            var want = stacked ? PosStacked : PosFree;
            Root.anchoredPosition = Vector2.MoveTowards(Root.anchoredPosition, want, 900f * dt);
            _clock += dt;
            _j.Tick(dt);
        }
    }
}
