using System.Collections.Generic;
using UnityEngine;
using Pitt.UI;

namespace Pitt.OnePit
{
    /// Safe area HUD зала (п. 105 из design-review 03.11, ?? пороги HIG iPhone 14 Pro: вырез ≥ 47–59 пт сверху, полоса жеста 34 пт снизу):
    /// слои Hud и Action сжимаются на отступы, поэтому всё, что прижато к их углам (деньги, шестерёнка, цель, «Прокачки», «Кинуть», ролик),
    /// сдвигается само. Слои Stick (джойстик ловит палец на всём экране), World, Sheet, Banners, Toasts — на весь экран.
    /// Отступ = max(Screen.safeArea устройства, пол): пол верха TopFloorPt, пола низа BottomFloorPt — чтобы и без выреза (веб, Android,
    /// кадры 390×844) шестерёнка не липла к краю, а нижние кнопки не лежали на полосе жеста. Единицы — px канваса 1080 (1 пт = 1080/390 px).
    /// Включается при постройке HUD зала (HallHud.Ensure); вне «Одной Ямы» слои не трогаются.
    public static class HudInset
    {
        public const float PxPerPt = 1080f / 390f;
        public const float TopFloorPt = 47f, BottomFloorPt = 34f;
        /// Отступы сейчас, px канваса (сверху, снизу, слева, справа).
        public static float Top, Bottom, Left, Right;
        public static bool On { get; private set; }
        static readonly List<RectTransform> _layers = new List<RectTransform>(2);
        static bool _hooked;

        [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.SubsystemRegistration)]
        static void ResetStatics() { Top = Bottom = Left = Right = 0f; On = false; _layers.Clear(); _hooked = false; }

        /// Центр слоя относительно центра канваса (px, y вверх): координаты «от центра канваса» (Game.WorldToUi, направления к краю) → локальные
        /// слоя вычитают его.
        public static Vector2 CenterShift => On ? new Vector2((Left - Right) * 0.5f, (Bottom - Top) * 0.5f) : Vector2.zero;

        /// Отступы для окна w×h пикселей с safeArea sa и масштабом канваса scale (px экрана на px канваса); pillarbox — боковые не берём.
        public static void Compute(Rect sa, int w, int h, float scale, bool fullWidth, out float top, out float bottom, out float left, out float right)
        {
            float k = 1f / Mathf.Max(0.05f, scale);
            top = Mathf.Max(TopFloorPt * PxPerPt, Mathf.Max(0f, h - sa.yMax) * k);
            bottom = Mathf.Max(BottomFloorPt * PxPerPt, Mathf.Max(0f, sa.yMin) * k);
            left = fullWidth ? Mathf.Max(0f, sa.xMin) * k : 0f;
            right = fullWidth ? Mathf.Max(0f, w - sa.xMax) * k : 0f;
        }

        public static void Enable(params RectTransform[] layers)
        {
            _layers.Clear();
            foreach (var l in layers) if (l) _layers.Add(l);
            On = true;
            if (!_hooked) { _hooked = true; ViewportFit.Changed += Refresh; }
            Refresh();
        }

        public static void Refresh()
        {
            if (!On) return;
            if (Game.IsSim || ViewportFit.Mode != "window" || Screen.width <= 0)
                Compute(new Rect(0f, 0f, 1f, 1f), 1, 1, 1f, false, out Top, out Bottom, out Left, out Right);   // кадр/sim: только пол
            else
                Compute(Screen.safeArea, Screen.width, Screen.height, ViewportFit.LastScale, ViewportFit.LastRect.width > 0.999f, out Top, out Bottom, out Left, out Right);
            for (int i = 0; i < _layers.Count; i++)
            {
                var l = _layers[i];
                if (!l) continue;
                l.offsetMin = new Vector2(Left, Bottom);
                l.offsetMax = new Vector2(-Right, -Top);
            }
        }
    }
}
